import { revalidateTag } from 'next/cache'
import { after } from 'next/server'
import { getCachedProducts } from '@/lib/products'
import { syncCatalogFromUpstream } from '@/lib/db'

export default async function CatalogPage() {
  const products = await getCachedProducts()

  async function syncCatalog() {
    'use server'

    // Run the upstream ERP/PIM sync after the response is sent so the
    // admin keeps working immediately.
    after(async () => {
      await syncCatalogFromUpstream()
    })

    // Stale-while-revalidate: existing cached data stays available while
    // every view tagged "products" refreshes in the background.
    revalidateTag('products', 'max')
  }

  return (
    <main style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <h1>Product catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <table cellPadding={8} style={{ marginTop: '1.5rem', borderCollapse: 'collapse' }}>
        <thead>
          <tr>
            <th align="left">ID</th>
            <th align="left">Name</th>
            <th align="left">Price</th>
            <th align="left">Last synced</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product: any) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
              <td>{product.syncedAt ?? '—'}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

